    {
      "name": "tasks",
      "fields": [
        {"name": "title", "type": "string"},
        {"name": "description", "type": "string"},
        {"name": "priority", "type": "string", "options": ["Low", "Medium", "High"]},
        {"name": "due_date", "type": "string"},
        {"name": "done", "type": "boolean"}
      ],
      "operations": ["list", "create", "update", "delete"]
    }
