{"thought":"Next, I'll implement the update_task function.","action":"implement","path":"database/tasks.py","content":"with connect(SCHEMA) as conn:
    cur = conn.execute("UPDATE tasks SET title = ?, description = ?, priority = ?, due_date = ?, done = ? WHERE id = ?", (title, description, priority, due_date, int(done), task_id))
    if cur.rowcount == 0:
        return None
    row = conn.execute("SELECT id, title, description, priority, due_date, done FROM tasks WHERE id = ?", (task_id,)).fetchone()
    return dict(row)","function":"update_task"}

